"use strict";
import { createColumnHelper } from "@tanstack/react-table";
import { Table } from "components/Table";
import { HeaderCell, EllipsisText } from "components/Table/styled";
import { MAX_WIDTH_MEDIA_BREAKPOINT } from "components/Tokens/constants";
import { VoteTokenSortMethod, sortAscendingAtom, sortMethodAtom, exploreSearchStringAtom } from "components/Tokens/state";
import { OrderDirection } from "graphql/data/util";
import { useAccount } from "hooks/useAccount";
import useSimplePagination from "hooks/useSimplePagination";
import { useVeABXUserLocks } from "hooks/useVeABXLocks";
import { useUserVotesForAllPools } from "hooks/useUserVotesForAllPools";
import { useAtomValue, useUpdateAtom } from "jotai/utils";
import { memo, useEffect, useMemo } from "react";
import { useAppSelector } from "state/hooks";
import { TABLE_PAGE_SIZE } from "state/explore";
import { selectSelectedLock } from "state/voting/slice";
import { Flex, styled, useMedia } from "ui/src";
import { formatUnits } from "viem";
import { GaugeDescription } from "./GaugeDescription";
import { GaugeTableHeader } from "./GaugeTableHeader";
import { FeesCell, IncentivesCell, TotalRewardsCell, VAPRCell } from "./GaugeTableCells";
const TableWrapper = styled(Flex, {
  m: "0 auto",
  maxWidth: MAX_WIDTH_MEDIA_BREAKPOINT
});
const EMPTY_VOTES = [];
export const VotePoolsTable = memo(function VotePoolsTable2({
  voteData
}) {
  const account = useAccount();
  const isConnected = Boolean(account.address);
  const { data: userLocks } = useVeABXUserLocks(isConnected ? account.address : void 0);
  useAppSelector(selectSelectedLock);
  const searchQuery = useAtomValue(exploreSearchStringAtom);
  const sortAscending = useAtomValue(sortAscendingAtom);
  const sortMethod = useAtomValue(sortMethodAtom);
  const setSortMethod = useUpdateAtom(sortMethodAtom);
  const orderDirection = sortAscending ? OrderDirection.Asc : OrderDirection.Desc;
  const media = useMedia();
  const { page, loadMore } = useSimplePagination();
  useEffect(() => {
    if (!Object.values(VoteTokenSortMethod).includes(sortMethod)) {
      setSortMethod(VoteTokenSortMethod.TOTAL_REWARDS);
    }
  }, [setSortMethod, sortMethod]);
  const filteredGauges = useMemo(() => {
    if (!voteData.gauges.length) {
      return [];
    }
    if (!searchQuery || searchQuery.trim() === "") {
      return voteData.gauges;
    }
    const query = searchQuery.toLowerCase().trim();
    return voteData.gauges.filter((gauge) => {
      const token0Symbol = gauge.token0?.symbol?.toLowerCase() ?? "";
      const token1Symbol = gauge.token1?.symbol?.toLowerCase() ?? "";
      const token0Name = gauge.token0?.name?.toLowerCase() ?? "";
      const token1Name = gauge.token1?.name?.toLowerCase() ?? "";
      const poolAddress = gauge.poolId.toLowerCase();
      return token0Symbol.includes(query) || token1Symbol.includes(query) || token0Name.includes(query) || token1Name.includes(query) || poolAddress.includes(query);
    });
  }, [voteData.gauges, searchQuery]);
  const visibleGauges = useMemo(
    () => filteredGauges.slice(0, page * TABLE_PAGE_SIZE),
    [filteredGauges, page]
  );
  const poolAddresses = useMemo(() => {
    return visibleGauges.map((g) => g.poolId).sort();
  }, [visibleGauges.map((g) => g.poolId).join(",")]);
  const { votesMap: onChainVotesMap } = useUserVotesForAllPools(poolAddresses, userLocks);
  const gaugeTableValues = useMemo(() => {
    return visibleGauges.map((gauge) => {
      const userVotes = onChainVotesMap.get(gauge.poolId) ?? EMPTY_VOTES;
      const feesUSD = gauge.epochStats.totalFeesPreviousEpochUsd;
      const incentivesUSD = gauge.epochStats.totalIncentivesCurrentEpochUsd;
      const totalRewardsUSD = gauge.epochStats.totalRewardsCurrentEpochUsd;
      return {
        gauge,
        userVotes,
        feesUSD,
        incentivesUSD,
        totalRewardsUSD
      };
    });
  }, [visibleGauges, onChainVotesMap]);
  const sortedGaugeTableValues = useMemo(() => {
    const sorted = [...gaugeTableValues];
    sorted.sort((a, b) => {
      let compareValue = 0;
      switch (sortMethod) {
        case VoteTokenSortMethod.POOLS: {
          const nameA = `${a.gauge.token0?.symbol || ""}/${a.gauge.token1?.symbol || ""}`.toLowerCase();
          const nameB = `${b.gauge.token0?.symbol || ""}/${b.gauge.token1?.symbol || ""}`.toLowerCase();
          compareValue = nameA.localeCompare(nameB);
          break;
        }
        case VoteTokenSortMethod.FEES: {
          compareValue = a.feesUSD - b.feesUSD;
          break;
        }
        case VoteTokenSortMethod.INCENTIVES: {
          compareValue = a.incentivesUSD - b.incentivesUSD;
          break;
        }
        case VoteTokenSortMethod.TOTAL_REWARDS: {
          compareValue = a.totalRewardsUSD - b.totalRewardsUSD;
          break;
        }
        case VoteTokenSortMethod.V_APR: {
          const aprA = a.gauge.voterApr ?? 0;
          const aprB = b.gauge.voterApr ?? 0;
          compareValue = aprA - aprB;
          break;
        }
        default:
          compareValue = 0;
      }
      return sortAscending ? compareValue : -compareValue;
    });
    return sorted;
  }, [gaugeTableValues, sortMethod, sortAscending]);
  const showLoadingSkeleton = voteData.isLoading || Boolean(voteData.error);
  const hasLocks = Boolean(userLocks && userLocks.length > 0);
  const userTotalVotingPower = useMemo(() => {
    if (!userLocks || userLocks.length === 0) return 0;
    return userLocks.reduce((total, lock) => {
      const votingPower = Number(formatUnits(BigInt(lock.votingPower || "0"), 18));
      return total + votingPower;
    }, 0);
  }, [userLocks]);
  const columns = useMemo(() => {
    const columnHelper = createColumnHelper();
    return [
      columnHelper.accessor((row) => row.gauge, {
        id: "gaugeName",
        size: media.lg ? 150 : 300,
        header: () => <HeaderCell justifyContent="flex-start">
            <GaugeTableHeader
          alignText="flex-start"
          category={VoteTokenSortMethod.POOLS}
          isCurrentSortMethod={sortMethod === VoteTokenSortMethod.POOLS}
          direction={orderDirection}
        />
          </HeaderCell>,
        cell: (context) => {
          const row = context.row?.original;
          if (!row) {
            return <HeaderCell
              className="gauge-name-header-cell"
              px={media.lg ? 0 : 8}
              width={"100%"}
              justifyContent="flex-start"
              alignItems="stretch"
              flex={1}
              loading={showLoadingSkeleton}
              testId="name-cell"
            >
                <EllipsisText>-</EllipsisText>
              </HeaderCell>;
          }
          return <HeaderCell
            className="gauge-name-header-cell"
            px={media.lg ? 0 : 8}
            width={"100%"}
            justifyContent="flex-start"
            alignItems="stretch"
            flex={1}
            loading={showLoadingSkeleton}
            testId="name-cell"
          >
              <GaugeDescription gauge={row.gauge} userVotes={row.userVotes} />
            </HeaderCell>;
        }
      }),
      columnHelper.accessor((row) => row.gauge, {
        id: "fees",
        minSize: 140,
        header: () => <HeaderCell justifyContent="flex-end">
            <GaugeTableHeader
          category={VoteTokenSortMethod.FEES}
          isCurrentSortMethod={sortMethod === VoteTokenSortMethod.FEES}
          direction={orderDirection}
        />
          </HeaderCell>,
        cell: (context) => {
          const gauge = context.row?.original?.gauge;
          if (!gauge) {
            return <HeaderCell
              px={8}
              alignItems="stretch"
              flex={1}
              loading={showLoadingSkeleton}
              testId="fees-cell"
            >
                <FeesCell rewards={[]} total={0} isLoading />
              </HeaderCell>;
          }
          return <HeaderCell
            px={8}
            alignItems="stretch"
            flex={1}
            loading={showLoadingSkeleton}
            testId="fees-cell"
          >
              <FeesCell
            rewards={gauge.epochStats.feeRewards}
            total={gauge.epochStats.totalFeesPreviousEpochUsd}
            isLoading={showLoadingSkeleton}
          />
            </HeaderCell>;
        }
      }),
      columnHelper.accessor((row) => row.gauge, {
        id: "incentives",
        minSize: 140,
        header: () => <HeaderCell justifyContent="flex-end">
            <GaugeTableHeader
          category={VoteTokenSortMethod.INCENTIVES}
          isCurrentSortMethod={sortMethod === VoteTokenSortMethod.INCENTIVES}
          direction={orderDirection}
        />
          </HeaderCell>,
        cell: (context) => {
          const gauge = context.row?.original?.gauge;
          if (!gauge) {
            return <HeaderCell
              px={8}
              alignItems="stretch"
              flex={1}
              loading={showLoadingSkeleton}
              testId="incentives-cell"
            >
                <IncentivesCell rewards={[]} total={0} isLoading />
              </HeaderCell>;
          }
          return <HeaderCell
            px={8}
            alignItems="stretch"
            flex={1}
            loading={showLoadingSkeleton}
            testId="incentives-cell"
          >
              <IncentivesCell
            rewards={gauge.epochStats.bribeRewards}
            total={gauge.epochStats.totalIncentivesCurrentEpochUsd}
            isLoading={showLoadingSkeleton}
          />
            </HeaderCell>;
        }
      }),
      columnHelper.accessor((row) => row.gauge, {
        id: "totalRewards",
        minSize: 120,
        header: () => <HeaderCell justifyContent="flex-end">
            <GaugeTableHeader
          category={VoteTokenSortMethod.TOTAL_REWARDS}
          isCurrentSortMethod={sortMethod === VoteTokenSortMethod.TOTAL_REWARDS}
          direction={orderDirection}
        />
          </HeaderCell>,
        cell: (context) => {
          const gauge = context.row?.original?.gauge;
          if (!gauge) {
            return <HeaderCell
              px={8}
              alignItems="stretch"
              flex={1}
              loading={showLoadingSkeleton}
              testId="total-rewards-cell"
            >
                <TotalRewardsCell
              rewards={{
                feeRewards: [],
                bribeRewards: [],
                totalFeesPreviousEpochUsd: 0,
                totalIncentivesCurrentEpochUsd: 0,
                emissionsDistributed: 0,
                totalRewardsCurrentEpochUsd: 0,
                rewardPerVeUsd: 0
              }}
              isLoading
            />
              </HeaderCell>;
          }
          return <HeaderCell
            px={8}
            alignItems="stretch"
            flex={1}
            loading={showLoadingSkeleton}
            testId="total-rewards-cell"
          >
              <TotalRewardsCell
            rewards={gauge.epochStats}
            isLoading={showLoadingSkeleton}
          />
            </HeaderCell>;
        }
      }),
      columnHelper.accessor((row) => row.gauge, {
        id: "vAPR",
        minSize: 170,
        header: () => <HeaderCell>
            <GaugeTableHeader
          category={VoteTokenSortMethod.V_APR}
          isCurrentSortMethod={sortMethod === VoteTokenSortMethod.V_APR}
          direction={orderDirection}
        />
          </HeaderCell>,
        cell: (context) => {
          const row = context.row?.original;
          if (!row) {
            return <HeaderCell px={8} alignItems="stretch" flex={1} loading testId="vapr-cell">
                <EllipsisText>-</EllipsisText>
              </HeaderCell>;
          }
          return <HeaderCell
            px={8}
            alignItems="stretch"
            flex={1}
            loading={showLoadingSkeleton}
            testId="vapr-cell"
          >
              <VAPRCell
            gauge={row.gauge}
            totalVotingPower={voteData.totals.totalVotingPower}
            userVotes={row.userVotes}
            hasLocks={hasLocks}
            userTotalVotingPower={userTotalVotingPower}
            isConnected={isConnected}
          />
            </HeaderCell>;
        }
      })
    ];
  }, [
    hasLocks,
    isConnected,
    media,
    orderDirection,
    showLoadingSkeleton,
    sortMethod,
    voteData.totals.totalVotingPower,
    userTotalVotingPower
  ]);
  return <TableWrapper data-testid="vote-gauges-table">
      <Table
    columns={columns}
    data={sortedGaugeTableValues}
    loading={voteData.isLoading}
    error={voteData.error}
    maxWidth={1200}
    loadMore={loadMore}
    tableType="vote"
    defaultPinnedColumns={["gaugeName"]}
  />
    </TableWrapper>;
});
