"use strict";
import { useQuery } from "@tanstack/react-query";
import { usePublicClient } from "wagmi";
import { getAbstractContracts } from "uniswap/src/constants/abstractContracts";
const VOTING_ESCROW_ABI = [
  {
    inputs: [],
    name: "supply",
    outputs: [{ internalType: "uint256", name: "", type: "uint256" }],
    stateMutability: "view",
    type: "function"
  },
  {
    inputs: [],
    name: "totalSupply",
    outputs: [{ internalType: "uint256", name: "", type: "uint256" }],
    stateMutability: "view",
    type: "function"
  }
];
export function useVeABXGlobalOnChain(chainId) {
  const publicClient = usePublicClient({ chainId });
  const contracts = getAbstractContracts(chainId);
  const votingEscrowAddress = contracts?.votingEscrow;
  return useQuery({
    queryKey: ["veabx-global-onchain", chainId, votingEscrowAddress],
    queryFn: async () => {
      if (!publicClient || !votingEscrowAddress) {
        return { totalLocked: 0n, totalSupply: 0n };
      }
      try {
        const results = await publicClient.multicall({
          contracts: [
            {
              address: votingEscrowAddress,
              abi: VOTING_ESCROW_ABI,
              functionName: "supply"
            },
            {
              address: votingEscrowAddress,
              abi: VOTING_ESCROW_ABI,
              functionName: "totalSupply"
            }
          ],
          allowFailure: true
        });
        const totalLocked = results[0].status === "success" ? results[0].result : 0n;
        const totalSupply = results[1].status === "success" ? results[1].result : 0n;
        return {
          totalLocked,
          totalSupply
        };
      } catch (error) {
        console.error("[useVeABXGlobalOnChain] Error fetching on-chain data:", error);
        return { totalLocked: 0n, totalSupply: 0n };
      }
    },
    staleTime: 3e4,
    // 30 seconds (fresher than subgraph!)
    refetchInterval: 6e4,
    // 1 minute
    enabled: Boolean(publicClient && votingEscrowAddress)
  });
}
